package run.ikaros.notes; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PrivateNoteRevisionService{private final PrivateNoteRepository notes;private final PrivateNoteRevisionRepository revisions;private final PrivateVaultRepository vaults;public PrivateNoteRevisionService(PrivateNoteRepository n,PrivateNoteRevisionRepository r,PrivateVaultRepository v){notes=n;revisions=r;vaults=v;}public Mono<NoteRevisionView> commit(UUID a,UUID id,CommitNoteRevisionRequest q){return notes.findById(id).filter(n->n.ownerId().equals(a)&&!n.tombstone()).switchIfEmpty(Mono.error(new NotFoundException("Private Note 不存在或无权访问"))).flatMap(n->{if(n.revision()!=q.expectedRevision())return Mono.error(new ConflictException("Private Note Revision 冲突"));long next=n.revision()+1;Instant now=Instant.now();return vaults.findById(n.vaultId()).filter(v->v.ownerId().equals(a)&&v.status()==VaultStatus.UNLOCKED).switchIfEmpty(Mono.error(new ConflictException("Private Vault 尚未解锁"))).then(notes.save(new PrivateNoteEntity(n.id(),n.vaultId(),n.notebookId(),a,q.encryptedTitle(),q.encryptedBody(),q.encryptedProperties(),next,false,n.createdAt(),now,n.version()))).then(revisions.save(new PrivateNoteRevisionEntity(null,id,n.vaultId(),a,next,q.encryptedTitle(),q.encryptedBody(),q.encryptedProperties(),now)));}).map(this::view);}public Flux<NoteRevisionView> history(UUID a,UUID id){return notes.findById(id).filter(n->n.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Private Note 不存在或无权访问"))).flatMapMany(n->vaults.findById(n.vaultId()).filter(v->v.ownerId().equals(a)&&v.status()==VaultStatus.UNLOCKED).switchIfEmpty(Mono.error(new ConflictException("Private Vault 尚未解锁"))).flatMapMany(v->revisions.findAllByNoteIdAndOwnerIdOrderByRevisionDesc(id,a).take(100).map(this::view)));}public Mono<PrivateNoteSyncView> sync(UUID a,UUID vaultId,Instant cursor){return vaults.findById(vaultId).filter(v->v.ownerId().equals(a)&&v.status()==VaultStatus.UNLOCKED).switchIfEmpty(Mono.error(new NotFoundException("Private Vault 不存在、无权访问或尚未解锁"))).flatMap(v->notes.findAllByVaultIdAndOwnerIdAndUpdatedAtGreaterThanOrderByUpdatedAtAsc(vaultId,a,cursor==null?Instant.EPOCH:cursor).take(100).collectList()).map(xs->{Instant next=xs.isEmpty()?Instant.now():xs.get(xs.size()-1).updatedAt();return new PrivateNoteSyncView(xs.stream().map(this::note).toList(),next);});}private NoteRevisionView view(PrivateNoteRevisionEntity x){return new NoteRevisionView(x.id(),x.noteId(),x.revision(),x.encryptedTitle(),x.encryptedBody(),x.encryptedProperties(),x.createdAt());}private NoteView note(PrivateNoteEntity n){return new NoteView(n.id(),n.vaultId(),n.notebookId(),n.encryptedTitle(),n.encryptedBody(),n.encryptedProperties(),n.revision(),n.tombstone(),n.createdAt(),n.updatedAt());}}
